REPLACE INTO `policies`
(`policies_id`, `title`, `category`, `region`, `publisher`, `summary`, `content`, `department`, `contact_person`, `phone`, `address`, `source_link`, `create_time`)
VALUES
('demo_policy_20260324_01', '商务部等九部门关于推动农村电商高质量发展的实施意见（展示版）', '营销帮扶', '全国', '商务部等九部门',
'围绕农村电商提质增效、供应链协同、县域商业体系和品牌培育等方向整理形成的展示版政策摘要，适合在助农商城中作为电商帮扶政策示例内容。',
'<h3>政策导向</h3><p>该政策聚焦农村电商高质量发展，强调完善县乡村三级物流配送体系，推动农产品上行与工业品下行协同发展，并提升农产品电商标准化、品牌化和数字化水平。</p><h3>展示重点</h3><ol><li><strong>流通体系建设</strong>：推进县域商业体系与农村电商协同联动，增强冷链仓储、物流配送和网点服务能力。</li><li><strong>电商主体培育</strong>：支持家庭农场、合作社、农业企业和本地服务商增强数字运营能力。</li><li><strong>品牌与营销</strong>：鼓励发展区域公用品牌、直播带货、节庆促销和线上线下融合展销场景。</li><li><strong>人才与运营</strong>：推动培训体系建设，提升返乡创业人员、电商运营人员和基层服务队伍的专业能力。</li></ol><h3>页面展示建议</h3><p>适合在商城政策中心展示为“营销帮扶”类政策，用于说明平台具备政策信息服务与助农电商导向宣传能力。</p>',
 '商务部流通发展司', '政策展示联系人', '010-85093792', '北京市东城区东长安街2号', 'https://www.mofcom.gov.cn/zcfb/gnmygl/art/2024/art_bcd035118a9145b9a86526a80318ce12.html', '2026-03-24 10:00:00'),

('demo_policy_20260324_02', '北京市关于促进农产品市场发展的若干措施（展示版）', '补贴政策', '北京市', '北京市商务局',
'围绕农产品市场建设、流通保障、品牌推广和惠农便民服务整理形成的展示版摘要，适合作为地方扶持政策示例内容。',
'<h3>政策导向</h3><p>该类措施通常面向农产品市场优化提升、产销对接和流通服务保障，重点关注市场设施提升、农产品保供稳价与区域品牌培育。</p><h3>展示重点</h3><ol><li><strong>市场建设支持</strong>：鼓励农产品市场完善基础设施、仓储能力和信息化服务。</li><li><strong>产销衔接</strong>：支持产地与销地开展长期合作，推动优质农产品进入城市消费市场。</li><li><strong>品牌培育</strong>：鼓励开展品牌宣传、展销推介和特色农产品消费促进活动。</li><li><strong>公共服务</strong>：提升惠农便民服务能力，强化农产品流通效率和质量监管。</li></ol><h3>页面展示建议</h3><p>适合在商城政策中心展示为“补贴政策”类内容，突出平台与地方市场建设、产销协同的结合场景。</p>',
 '北京市商务局市场运行处', '政策展示联系人', '010-55579418', '北京市通州区运河东大街57号院', 'https://sw.beijing.gov.cn/phone/zwxx/2024zcwjphone/202509/t20250928_4212982.html', '2026-03-24 10:05:00'),

('demo_policy_20260324_03', '宁夏“数商兴农年”活动工作安排（展示版）', '教育培训', '宁夏回族自治区', '宁夏回族自治区商务厅',
'结合公开活动通知整理形成的展示版内容，突出电商培训、产销对接、直播助农和品牌推广等助农场景。',
'<h3>政策导向</h3><p>该类活动以“数商兴农”为抓手，重点推动农产品网络销售增长、县域电商主体培育和线上促消费活动开展。</p><h3>展示重点</h3><ol><li><strong>培训提升</strong>：组织农户、电商从业者、合作社负责人参与运营培训和直播技能培训。</li><li><strong>活动带动</strong>：开展线上专题促销、直播推介、区域品牌宣传和特色产品展销活动。</li><li><strong>渠道拓展</strong>：引导农产品与平台、商超、供应链企业建立更加稳定的销售协作关系。</li><li><strong>示范培育</strong>：培育一批数字化营销示范主体，形成可复制的助农电商案例。</li></ol><h3>页面展示建议</h3><p>适合展示为“教育培训”类政策，体现平台不仅能售卖农产品，也关注电商人才培养与经营能力提升。</p>',
 '宁夏回族自治区商务厅电子商务和信息中心', '政策展示联系人', '0951-5960705', '银川市兴庆区民族北街435号', 'https://dofcom.nx.gov.cn/zlzt/lgnx/rmhd/zbdsj/202407/t20240723_4602137.html', '2026-03-24 10:10:00'),

('demo_policy_20260324_04', '科技特派员助力乡村振兴服务案例（展示版）', '技术支持', '湖北省', '湖北省科学技术厅',
'根据公开科技特派员服务乡村振兴案例整理形成的展示版摘要，突出技术服务、田间指导和产业帮扶的实际作用。',
'<h3>政策导向</h3><p>科技特派员服务强调将农业技术、种养方案、病虫害防治和产业指导送到田间地头，提升农业生产效率与经营质量。</p><h3>展示重点</h3><ol><li><strong>下沉服务</strong>：围绕粮油、果蔬、中药材和特色产业开展现场指导。</li><li><strong>技术培训</strong>：面向种植户、合作社和经营主体开展专题培训和跟踪服务。</li><li><strong>成果转化</strong>：促进新品种、新技术和绿色生产方式在基层落地。</li><li><strong>产业支撑</strong>：帮助农业主体解决生产技术难题，增强可持续经营能力。</li></ol><h3>页面展示建议</h3><p>适合作为“技术支持”类政策展示，丰富平台内容层次，让页面不只停留在补贴或营销层面。</p>',
 '湖北省科学技术厅农村科技处', '政策展示联系人', '027-87135656', '武汉市武昌区水果湖街道', 'https://kjt.hubei.gov.cn/kjdt/sxkj/hg/202412/t20241209_5443219.shtml', '2026-03-24 10:15:00'),

('demo_policy_20260324_05', '促进农产品消费实施方案（展示版）', '营销帮扶', '全国', '农业农村部等十部门',
'基于公开报道整理的展示版摘要，聚焦绿色优质供给、消费场景创新、产销对接和平台协同，适合作为全国层面的政策示例内容。',
'<h3>政策导向</h3><p>该实施方案主要围绕扩大农产品消费、提升绿色优质供给水平、创新消费场景和强化品牌引领等方面展开。</p><h3>展示重点</h3><ol><li><strong>优质供给</strong>：鼓励发展绿色、有机、地理标志等优质农产品，提升产品分级和品质表达能力。</li><li><strong>场景创新</strong>：拓展展会消费、节庆消费、农文旅融合消费等多样化场景。</li><li><strong>平台协同</strong>：发挥电商平台和流通渠道优势，推动产销精准对接。</li><li><strong>品牌增值</strong>：加强宣传推广和消费引导，提升特色农产品的市场辨识度与认可度。</li></ol><h3>页面展示建议</h3><p>适合在商城中作为全国导向型“营销帮扶”示例政策展示，用于增强首页和政策页的完整度与可信度。</p>',
 '农业农村部市场与信息化司', '政策展示联系人', '010-59192600', '北京市朝阳区农展馆南里11号', 'https://scjc.gov.cn/scjc/syjdxw/2025/7/28/d0f88d0a16324844a39797451b6f01af.shtml', '2026-03-24 10:20:00');
